// This file was auto-generated from sdk-root/src/data/observabilityadmin/2018-05-10/docs-2.json
return [ 'version' => '2.0', 'service' => '<p> You can use Amazon CloudWatch Observability Admin to discover and understand the state of telemetry configuration in CloudWatch for your Amazon Web Services Organization or account. This simplifies the process of auditing your telemetry collection configurations across multiple resource types within your Amazon Web Services Organization or account. By providing a consolidated view, it allows you to easily review and manage telemetry settings, helping you ensure proper monitoring and data collection across your Amazon Web Services environment. For more information, see <a href="https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/telemetry-config-cloudwatch.html">Auditing CloudWatch telemetry conﬁgurations</a> in the CloudWatch User Guide.</p> <p>For information on the permissions you need to use this API, see <a href="https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/auth-and-access-control-cw.html">Identity and access management for Amazon CloudWatch</a> in the CloudWatch User Guide.</p>', 'operations' => [ 'CreateCentralizationRuleForOrganization' => '<p>Creates a centralization rule that applies across an Amazon Web Services Organization. This operation can only be called by the organization\'s management account or a delegated administrator account.</p>', 'CreateConnector' => '<p>Creates a connector to a third-party cloud provider. With a connector, you can discover resources in the provider and collect their telemetry. Currently, Microsoft Azure is the only supported provider.</p>', 'CreateDatasetIntegration' => '<p>Creates a dataset integration for the caller\'s account in the current region and returns its ARN.</p> <p>To use this operation, you must have permission to access the dataset integration resources through the IAM role specified in the <code>RoleArn</code> parameter.</p> <p>If a dataset integration already exists for the account, this operation fails with a <code>ConflictException</code>.</p>', 'CreateS3TableIntegration' => '<p>Creates an integration between CloudWatch and S3 Tables for analytics. This integration enables querying CloudWatch telemetry data using analytics engines like Amazon Athena, Amazon Redshift, and Apache Spark.</p>', 'CreateTelemetryPipeline' => '<p>Creates a telemetry pipeline for processing and transforming telemetry data. The pipeline defines how data flows from sources through processors to destinations, enabling data transformation and delivering capabilities. </p>', 'CreateTelemetryRule' => '<p> Creates a telemetry rule that defines how telemetry should be configured for Amazon Web Services resources in your account. The rule specifies which resources should have telemetry enabled and how that telemetry data should be collected based on resource type, telemetry type, and selection criteria. </p>', 'CreateTelemetryRuleForOrganization' => '<p> Creates a telemetry rule that applies across an Amazon Web Services Organization. This operation can only be called by the organization\'s management account or a delegated administrator account. </p>', 'DeleteCentralizationRuleForOrganization' => '<p>Deletes an organization-wide centralization rule. This operation can only be called by the organization\'s management account or a delegated administrator account.</p>', 'DeleteConnector' => '<p>Deletes a connector and its telemetry manifest.</p>', 'DeleteDatasetIntegration' => '<p>Deletes a dataset integration for the caller\'s account in the current region. This operation is idempotent; if you submit the same delete more than once, each call succeeds.</p>', 'DeleteS3TableIntegration' => '<p>Deletes an S3 Table integration and its associated data. This operation removes the connection between CloudWatch Observability Admin and S3 Tables.</p>', 'DeleteTelemetryPipeline' => '<p>Deletes a telemetry pipeline and its associated resources. This operation stops data processing and removes the pipeline configuration.</p>', 'DeleteTelemetryRule' => '<p> Deletes a telemetry rule from your account. Any telemetry configurations previously created by the rule will remain but no new resources will be configured by this rule. </p>', 'DeleteTelemetryRuleForOrganization' => '<p> Deletes an organization-wide telemetry rule. This operation can only be called by the organization\'s management account or a delegated administrator account. </p>', 'GetCentralizationRuleForOrganization' => '<p>Retrieves the details of a specific organization centralization rule. This operation can only be called by the organization\'s management account or a delegated administrator account.</p>', 'GetConnector' => '<p>Retrieves the details of a connector.</p>', 'GetConnectorTelemetryManifest' => '<p>Retrieves the telemetry manifest of a connector and its current version. If the connector has no telemetry manifest, this operation returns a <code>ResourceNotFoundException</code>.</p>', 'GetConnectorTelemetrySetup' => '<p>Generates the artifacts that you use to create the infrastructure in your cloud provider that delivers the telemetry declared in the connector\'s telemetry manifest. This operation doesn\'t change any resources in your cloud provider or in Amazon Web Services.</p>', 'GetDatasetIntegration' => '<p>Returns the dataset integration for the caller\'s account in the current region.</p>', 'GetS3TableIntegration' => '<p>Retrieves information about a specific S3 Table integration, including its configuration, status, and metadata.</p>', 'GetTelemetryEnrichmentStatus' => '<p> Returns the current status of the resource tags for telemetry feature, which enhances telemetry data with additional resource metadata from Resource Explorer. </p>', 'GetTelemetryEvaluationStatus' => '<p> Returns the current onboarding status of the telemetry config feature, including the status of the feature and reason the feature failed to start or stop. </p>', 'GetTelemetryEvaluationStatusForOrganization' => '<p> This returns the onboarding status of the telemetry configuration feature for the organization. It can only be called by a Management Account of an Amazon Web Services Organization or an assigned Delegated Admin Account of Amazon CloudWatch telemetry config. </p>', 'GetTelemetryPipeline' => '<p>Retrieves information about a specific telemetry pipeline, including its configuration, status, and metadata.</p>', 'GetTelemetryRule' => '<p> Retrieves the details of a specific telemetry rule in your account. </p>', 'GetTelemetryRuleForOrganization' => '<p> Retrieves the details of a specific organization telemetry rule. This operation can only be called by the organization\'s management account or a delegated administrator account. </p>', 'GetThirdPartyTelemetryEnrichment' => '<p>Returns the details of a third-party telemetry enrichment, including its status and source configuration.</p>', 'ListCentralizationRulesForOrganization' => '<p>Lists all centralization rules in your organization. This operation can only be called by the organization\'s management account or a delegated administrator account.</p>', 'ListConnectors' => '<p>Lists the connectors in the account and Region. This operation returns results in pages. To get the next page, pass the returned <code>NextToken</code> in the next call. We recommend that you use pagination to ensure that the operation returns quickly and successfully.</p>', 'ListDatasetIntegrations' => '<p>Returns the dataset integrations in your account.</p>', 'ListResourceTelemetry' => '<p> Returns a list of telemetry configurations for Amazon Web Services resources supported by telemetry config. For more information, see <a href="https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/telemetry-config-cloudwatch.html">Auditing CloudWatch telemetry configurations</a>. </p>', 'ListResourceTelemetryForOrganization' => '<p> Returns a list of telemetry configurations for Amazon Web Services resources supported by telemetry config in the organization. </p>', 'ListResourcesByConnector' => '<p>Lists resources in your cloud provider that the connector can access, such as management groups, subscriptions, resource types, Regions, resources, and Event Hubs. Use the results to build a telemetry manifest. This operation returns results in pages. To get the next page, pass the returned <code>NextToken</code> in the next call. We recommend that you use pagination to ensure that the operation returns quickly and successfully.</p>', 'ListS3TableIntegrations' => '<p>Lists all S3 Table integrations in your account. We recommend using pagination to ensure that the operation returns quickly and successfully.</p>', 'ListTagsForResource' => '<p> Lists all tags attached to the specified resource. Supports telemetry rule resources, telemetry pipeline resources, and third-party telemetry enrichment resources. </p>', 'ListTelemetryPipelines' => '<p>Returns a list of telemetry pipelines in your account. Returns up to 100 results. If more than 100 telemetry pipelines exist, include the <code>NextToken</code> value from the response to retrieve the next set of results.</p>', 'ListTelemetryRules' => '<p> Lists all telemetry rules in your account. You can filter the results by specifying a rule name prefix. </p>', 'ListTelemetryRulesForOrganization' => '<p> Lists all telemetry rules in your organization. This operation can only be called by the organization\'s management account or a delegated administrator account. </p>', 'ListThirdPartyTelemetryEnrichments' => '<p>Returns a summary of each third-party telemetry enrichment in your account and Region. To get the full configuration of an enrichment, use <code>GetThirdPartyTelemetryEnrichment</code>. The results are paginated. To get the next page of results, use <code>NextToken</code>.</p>', 'PutConnectorTelemetryManifest' => '<p>Creates or replaces the telemetry manifest of a connector. The telemetry manifest declares which resources in your cloud provider to collect telemetry from and which telemetry types to collect. To avoid overwriting changes made by another caller, specify <code>ExpectedVersion</code>.</p>', 'StartTelemetryEnrichment' => '<p> Enables the resource tags for telemetry feature for your account, which enhances telemetry data with additional resource metadata from Resource Explorer to provide richer context for monitoring and observability. </p>', 'StartTelemetryEvaluation' => '<p> This action begins onboarding the caller Amazon Web Services account to the telemetry config feature. </p>', 'StartTelemetryEvaluationForOrganization' => '<p> This actions begins onboarding the organization and all member accounts to the telemetry config feature. </p>', 'StartTelemetryPipelineRefresh' => '<p>Starts a refresh of an external-cloud telemetry pipeline. The refresh re-reads the connector\'s telemetry manifest and re-discovers the sources in scope.</p> <p>The pipeline must be in the <code>ACTIVE</code> or <code>UPDATE_FAILED</code> state, with no refresh already running. You can use <code>GetTelemetryPipeline</code> to track the refresh.</p>', 'StartThirdPartyTelemetryEnrichment' => '<p>Starts a third-party telemetry enrichment. An enrichment adds resource metadata, such as tags, from a third-party telemetry source to the telemetry that CloudWatch receives from the resources of that source.</p> <p>You specify an Amazon Web Services Config connector for your third-party environment, such as a Microsoft Azure tenant. You can use each connector for only one enrichment.</p> <p>To use this operation, you must have the <code>config:PutThirdPartyServiceLinkedConfigurationRecorder</code> permission. If the Amazon Web Services Config service-linked role does not exist in your account, you must also have the <code>iam:CreateServiceLinkedRole</code> permission.</p>', 'StopTelemetryEnrichment' => '<p> Disables the resource tags for telemetry feature for your account, stopping the enhancement of telemetry data with additional resource metadata. </p>', 'StopTelemetryEvaluation' => '<p> This action begins offboarding the caller Amazon Web Services account from the telemetry config feature. </p>', 'StopTelemetryEvaluationForOrganization' => '<p> This action offboards the Organization of the caller Amazon Web Services account from the telemetry config feature. </p>', 'StopThirdPartyTelemetryEnrichment' => '<p>Stops a third-party telemetry enrichment. CloudWatch stops adding resource metadata from the third-party telemetry source to your telemetry.</p> <p>To use this operation, you must have the <code>config:DeleteServiceLinkedConfigurationRecorder</code> permission.</p>', 'TagResource' => '<p> Adds or updates tags for a resource. Supports telemetry rule resources, telemetry pipeline resources, and third-party telemetry enrichment resources. </p>', 'TestTelemetryPipeline' => '<p>Tests a pipeline configuration with sample records to validate data processing before deployment. This operation helps ensure your pipeline configuration works as expected. </p>', 'UntagResource' => '<p> Removes tags from a resource. Supports telemetry rule resources, telemetry pipeline resources, and third-party telemetry enrichment resources. </p>', 'UpdateCentralizationRuleForOrganization' => '<p>Updates an existing centralization rule that applies across an Amazon Web Services Organization. This operation can only be called by the organization\'s management account or a delegated administrator account.</p>', 'UpdateDatasetIntegration' => '<p>Updates a dataset integration for the caller\'s account in the current region. This operation is idempotent; if you submit the same update more than once, each call succeeds.</p>', 'UpdateTelemetryPipeline' => '<p>Updates the configuration of an existing telemetry pipeline.</p> <note> <p>The following attributes cannot be updated after pipeline creation:</p> <ul> <li> <p> <b>Pipeline name</b> - The pipeline name is immutable</p> </li> <li> <p> <b>Pipeline ARN</b> - The ARN is automatically generated and cannot be changed</p> </li> <li> <p> <b>Source type</b> - Once a pipeline is created with a specific source type (such as S3, CloudWatch Logs, GitHub, or third-party sources), it cannot be changed to a different source type</p> </li> </ul> <p>Processors can be added, removed, or modified. However, some processors are not supported for third-party pipelines and cannot be added through updates.</p> </note> <p> <b>Source-Specific Update Rules</b> </p> <dl> <dt>CloudWatch Logs Sources (Vended and Custom)</dt> <dd> <p> <b>Updatable:</b> <code>sts_role_arn</code> </p> <p> <b>Fixed:</b> <code>data_source_name</code>, <code>data_source_type</code>, sink (must remain <code>@original</code>)</p> </dd> <dt>S3 Sources (Crowdstrike, Zscaler, SentinelOne, Custom)</dt> <dd> <p> <b>Updatable:</b> All SQS configuration parameters, <code>sts_role_arn</code>, codec settings, compression type, bucket ownership settings, sink log group</p> <p> <b>Fixed:</b> <code>notification_type</code>, <code>aws.region</code> </p> </dd> <dt>GitHub Audit Logs</dt> <dd> <p> <b>Updatable:</b> All Amazon Web Services Secrets Manager attributes, <code>scope</code> (can switch between ORGANIZATION/ENTERPRISE), <code>organization</code> or <code>enterprise</code> name, <code>range</code>, authentication credentials (PAT or GitHub App)</p> </dd> <dt>Microsoft Sources (Entra ID, Office365, Windows)</dt> <dd> <p> <b>Updatable:</b> All Amazon Web Services Secrets Manager attributes, <code>tenant_id</code>, <code>workspace_id</code> (Windows only), OAuth2 credentials (<code>client_id</code>, <code>client_secret</code>)</p> </dd> <dt>Okta Sources (SSO, Auth0)</dt> <dd> <p> <b>Updatable:</b> All Amazon Web Services Secrets Manager attributes, <code>domain</code>, <code>range</code>, OAuth2 credentials (<code>client_id</code>, <code>client_secret</code>)</p> </dd> <dt>Palo Alto Networks</dt> <dd> <p> <b>Updatable:</b> All Amazon Web Services Secrets Manager attributes, <code>hostname</code>, basic authentication credentials (<code>username</code>, <code>password</code>)</p> </dd> <dt>ServiceNow CMDB</dt> <dd> <p> <b>Updatable:</b> All Amazon Web Services Secrets Manager attributes, <code>instance_url</code>, <code>range</code>, OAuth2 credentials (<code>client_id</code>, <code>client_secret</code>)</p> </dd> <dt>Wiz CNAPP</dt> <dd> <p> <b>Updatable:</b> All Amazon Web Services Secrets Manager attributes, <code>region</code>, <code>range</code>, OAuth2 credentials (<code>client_id</code>, <code>client_secret</code>)</p> </dd> </dl>', 'UpdateTelemetryRule' => '<p> Updates an existing telemetry rule in your account. If multiple users attempt to modify the same telemetry rule simultaneously, a ConflictException is returned to provide specific error information for concurrent modification scenarios. </p>', 'UpdateTelemetryRuleForOrganization' => '<p> Updates an existing telemetry rule that applies across an Amazon Web Services Organization. This operation can only be called by the organization\'s management account or a delegated administrator account. </p>', 'ValidateTelemetryPipelineConfiguration' => '<p>Validates a pipeline configuration without creating the pipeline. This operation checks the configuration for syntax errors and compatibility issues.</p>', ], 'shapes' => [ 'AccessDeniedException' => [ 'base' => '<p> Indicates you don\'t have permissions to perform the requested operation. The user or role that is making the request must have at least one IAM permissions policy attached that grants the required permissions. For more information, see <a href="https://docs.aws.amazon.com/IAM/latest/UserGuide/access.html">Access management for Amazon Web Services resources</a> in the IAM user guide. </p>', 'refs' => [], ], 'AccountIdentifier' => [ 'base' => NULL, 'refs' => [ 'AccountIdentifiers$member' => NULL, 'CentralizationRuleDestination$Account' => '<p>The destination account (within the organization) to which the telemetry data should be centralized.</p>', 'TelemetryConfiguration$AccountIdentifier' => '