 'refs' => [ 'ListCentralizationRulesForOrganizationInput$AllRegions' => '<p>A flag determining whether to return organization centralization rules from all regions or only the current region.</p>', 'TelemetryRule$AllowFieldUpdates' => '<p> If set to <code>true</code>, Amazon CloudWatch Observability Admin detects and remediates configuration drift in telemetry resources that it manages. For example, if a VPC flow log\'s format, traffic type, or aggregation interval no longer matches the rule\'s destination configuration, the flow log is replaced with one that matches. Only Observability Admin-managed resources are updated; customer-created resources are never modified. Currently supported for <code>AWS::EC2::VPC</code> resources (VPC flow logs). </p>', ], ], 'CentralizationFailureReason' => [ 'base' => NULL, 'refs' => [ 'CentralizationRuleSummary$FailureReason' => '<p>The reason why an organization centralization rule is marked UNHEALTHY.</p>', 'GetCentralizationRuleForOrganizationOutput$FailureReason' => '<p>The reason why an organization centralization rule is marked UNHEALTHY.</p>', ], ], 'CentralizationRule' => [ 'base' => '<p>Defines how telemetry data should be centralized across an Amazon Web Services Organization, including source and destination configurations.</p>', 'refs' => [ 'CreateCentralizationRuleForOrganizationInput$Rule' => '<p>The configuration details for the organization-wide centralization rule, including the source configuration and the destination configuration to centralize telemetry data across the organization.</p>', 'GetCentralizationRuleForOrganizationOutput$CentralizationRule' => '<p>The configuration details for the organization centralization rule.</p>', 'UpdateCentralizationRuleForOrganizationInput$Rule' => '<p>The configuration details for the organization-wide centralization rule, including the source configuration and the destination configuration to centralize telemetry data across the organization.</p>', ], ], 'CentralizationRuleDestination' => [ 'base' => '<p>Configuration specifying the primary destination for centralized telemetry data.</p>', 'refs' => [ 'CentralizationRule$Destination' => '<p>Configuration determining where the telemetry data should be centralized, backed up, as well as encryption configuration for the primary and backup destinations.</p>', ], ], 'CentralizationRuleSource' => [ 'base' => '<p>Configuration specifying the source of telemetry data to be centralized.</p>', 'refs' => [ 'CentralizationRule$Source' => '<p>Configuration determining the source of the telemetry data to be centralized.</p>', ], ], 'CentralizationRuleSummaries' => [ 'base' => NULL, 'refs' => [ 'ListCentralizationRulesForOrganizationOutput$CentralizationRuleSummaries' => '<p>A list of centralization rule summaries.</p>', ], ], 'CentralizationRuleSummary' => [ 'base' => '<p>A summary of a centralization rule\'s key properties and status.</p>', 'refs' => [ 'CentralizationRuleSummaries$member' => NULL, ], ], 'ClientToken' => [ 'base' => NULL, 'refs' => [ 'CreateConnectorInput$ClientToken' => '<p>A unique, case-sensitive identifier that you provide to ensure the operation completes no more than one time. If you use an Amazon Web Services SDK, the SDK generates this value and reuses it on retries. If this token matches a previous request with the same parameters, the service returns the connector from the first request without an error. If you use the same token with different parameters, including different tags, the service returns a <code>ValidationException</code>. This operation is idempotent when you use the same token and parameters.</p>', 'PutConnectorTelemetryManifestInput$ClientToken' => '<p>A unique, case-sensitive identifier that you provide to ensure the operation completes no more than one time. If you use an Amazon Web Services SDK, the SDK generates this value and reuses it on retries. If this token matches a previous request with the same telemetry manifest, the service returns the stored version without an error. If you use the same token with a different telemetry manifest, the service returns a <code>ValidationException</code>. This operation is idempotent when you use the same token and parameters.</p>', ], ], 'CloudtrailParameters' => [ 'base' => '<p> Parameters specific to Amazon Web Services CloudTrail telemetry configuration. </p>', 'refs' => [ 'TelemetryDestinationConfiguration$CloudtrailParameters' => '<p> Configuration parameters specific to Amazon Web Services CloudTrail when CloudTrail is the source type. </p>', ], ], 'Condition' => [ 'base' => '<p> A single condition that can match based on WAF rule action or label name. </p>', 'refs' => [ 'Conditions$member' => NULL, ], ], 'Conditions' => [ 'base' => '<p> A list of conditions for filter matching, with at least one condition required. </p>', 'refs' => [ 'Filter$Conditions' => '<p> The list of conditions that determine if a log record matches this filter. </p>', ], ], 'ConfigurationSummary' => [ 'base' => '<p>Provides a summary of pipeline configuration components including sources, processors, and destinations.</p>', 'refs' => [ 'TelemetryPipeline$ConfigurationSummary' => '<p>A summary of the pipeline configuration components.</p>', 'TelemetryPipelineSummary$ConfigurationSummary' => '<p>A summary of the pipeline configuration components.</p>', ], ], 'ConflictException' => [ 'base' => '<p> The requested operation conflicts with the current state of the specified resource or with another request. </p>', 'refs' => [], ], 'Connector' => [ 'base' => '<p>A connector to a third-party cloud provider.</p>', 'refs' => [ 'CreateConnectorOutput$Connector' => '<p>The connector that this request created.</p>', 'GetConnectorOutput$Connector' => '<p>The connector.</p>', ], ], 'ConnectorConfiguration' => [ 'base' => '<p>The configuration for connecting to a third-party cloud provider. Specify one provider.</p>', 'refs' => [ 'Connector$ConnectorConfiguration' => '<p>The configuration for connecting to the third-party cloud provider.</p>', 'CreateConnectorInput$ConnectorConfiguration' => '<p>The configuration for connecting to the third-party cloud provider.</p>', ], ], 'ConnectorIdentifier' => [ 'base' => NULL, 'refs' => [ 'DeleteConnectorInput$ConnectorIdentifier' => '<p>The connector to delete. Specify one of the following:</p> <ul> <li> <p>The Amazon Resource Name (ARN) of the connector</p> </li> <li> <p>The ID of the connector</p> </li> </ul>', 'GetConnectorInput$ConnectorIdentifier' => '<p>The connector. Specify one of the following:</p> <ul> <li> <p>The Amazon Resource Name (ARN) of the connector</p> </li> <li> <p>The ID of the connector</p> </li> </ul>', 'GetConnectorTelemetryManifestInput$ConnectorIdentifier' => '<p>The connector. Specify one of the following:</p> <ul> <li> <p>The Amazon Resource Name (ARN) of the connector</p> </li> <li> <p>The ID of the connector</p> </li> </ul>', 'GetConnectorTelemetrySetupInput$ConnectorIdentifier' => '<p>The connector whose telemetry manifest you want to generate the setup from. Specify one of the following:</p> <ul> <li> <p>The Amazon Resource Name (ARN) of the connector</p> </li> <li> <p>The ID of the connector</p> </li> </ul>', 'ListResourcesByConnectorInput$ConnectorIdentifier' => '<p>The connector to use for the query. Specify one of the following:</p> <ul> <li> <p>The Amazon Resource Name (ARN) of the connector</p> </li> <li> <p>The ID of the connector</p> </li> </ul>', 'PutConnectorTelemetryManifestInput$ConnectorIdentifier' => '<p>The connector. Specify one of the following:</p> <ul> <li> <p>The Amazon Resource Name (ARN) of the connector</p> </li> <li> <p>The ID of the connector</p> </li> </ul>', ], ], 'ConnectorName' => [ 'base' => NULL, 'refs' => [ 'Connector$Name' => '<p>The name of the connector.</p>', 'ConnectorSummary$Name' => '<p>The name of the connector.</p>', 'CreateConnectorInput$Name' => '<p>The name of the connector. The name must be unique in the account and Region (case-sensitive). If another connector already uses the name, the request fails with a <code>ConflictException</code>.</p> <p>The name can contain letters, digits, hyphens (-), underscores (_) and periods (.), and must start with a letter.</p>', ], ], 'ConnectorNextToken' => [ 'base' => NULL, 'refs' => [ 'ListConnectorsInput$NextToken' => '<p>The token for the next page of results, returned by a previous call.</p>', 'ListConnectorsOutput$NextToken' => '<p>The token to use in the next call to get the next page of results. Absent when there are no more results.</p>', 'ListResourcesByConnectorInput$NextToken' => '<p>The token for the next page of results, returned by a previous call.</p>', 'ListResourcesByConnectorOutput$NextToken' => '<p>The token to use in the next call to get the next page of results. Absent when there are no more results.</p>', ], ], 'ConnectorProvider' => [ 'base' => NULL, 'refs' => [ 'Connector$Provider' => '<p>The cloud provider that the connector connects to.</p>', 'ConnectorSummary$Provider' => '<p>The cloud provider that the connector connects to.</p>', 'GetConnectorTelemetrySetupOutput$Provider' => '<p>The cloud provider that the setup artifacts are for.</p>', ], ], 'ConnectorQuery' => [ 'base' => '<p>What to list in a cloud provider. Specify one provider.</p>', 'refs' => [ 'ListResourcesByConnectorInput$Selector' => '<p>What to list: one cloud provider, and one type of resource in that provider.</p>', ], ], 'ConnectorQueryResults' => [ 'base' => '<p>The results of a query. The populated member matches the member of the query.</p>', 'refs' => [ 'ListResourcesByConnectorOutput$Results' => '<p>The results, in the same shape as the <code>Selector</code> that you specified.</p>', ], ], 'ConnectorSummaries' => [ 'base' => NULL, 'refs' => [ 'ListConnectorsOutput$ConnectorSummaries' => '<p>The connectors in the account and Region.</p>', ], ], 'ConnectorSummary' => [ 'base' => '<p>Summary information about a connector.</p>', 'refs' => [ 'ConnectorSummaries$member' => NULL, ], ], 'ContextGraphStatus' => [ 'base' => '<p>The status of context graph centralization for a centralization rule. This status is independent of the overall <code>RuleHealth</code> for log delivery. Returns <code>Provisioning</code> while the context graph is being set up, <code>Healthy</code> once it is active, or <code>Unhealthy</code> if provisioning failed.</p>', 'refs' => [ 'CentralizationRuleSummary$ContextGraphStatus' => '<p>The status of context graph centralization for this rule. Returns <code>Provisioning</code> while the context graph is being set up, <code>Healthy</code> once it is active, or <code>Unhealthy</code> if provisioning failed. This status is independent of the overall <code>RuleHealth</code> for log delivery.</p>', 'GetCentralizationRuleForOrganizationOutput$ContextGraphStatus' => '<p>The status of context graph centralization for this rule. Returns <code>Provisioning</code> while the context graph is being set up, <code>Healthy</code> once it is active, or <code>Unhealthy</code> if provisioning failed. This status is independent of the overall <code>RuleHealth</code> for log delivery.</p>', ], ], 'CreateCentralizationRuleForOrganizationInput' => [ 'base' => NULL, 'refs' => [], ], 'CreateCentralizationRuleForOrganizationOutput' => [ 'base' => NULL, 'refs' => [], ], 'CreateConnectorInput' => [ 'base' => NULL, 'refs' => [], ], 'CreateConnectorOutput' => [ 'base' => NULL, 'refs' => [], ], 'CreateDatasetIntegrationInput' => [ 'base' => NULL, 'refs' => [], ], 'CreateDatasetIntegrationOutput' => [ 'base' => NULL, 'refs' => [], ], 'CreateS3TableIntegrationInput' => [ 'base' => NULL, 'refs' => [], ], 'CreateS3TableIntegrationOutput' => [ 'base' => NULL, 'refs' => [], ], 'CreateTelemetryPipelineInput' => [ 'base' => NULL, 'refs' => [], ], 'CreateTelemetryPipelineOutput' => [ 'base' => NULL, 'refs' => [], ], 'CreateTelemetryRuleForOrganizationInput' => [ 'base' => NULL, 'refs' => [], ], 'CreateTelemetryRuleForOrganizationOutput' => [ 'base' => NULL, 'refs' => [], ], 'CreateTelemetryRuleInput' => [ 'base' => NULL, 'refs' => [], ], 'CreateTelemetryRuleOutput' => [ 'base' => NULL, 'refs' => [], ], 'DataSource' => [ 'base' => '<p>Information about a data source associated with the telemetry pipeline. For CloudWatch Logs sources, this includes both a name and type extracted from the log event metadata. For third-party sources (such as S3), this includes only a name, with the type field left empty.</p>', 'refs' => [ 'DataSources$member' => NULL, ], ], 'DataSourceFilterString' => [ 'base' => NULL, 'refs' => [ 'SourceLogsConfiguration$DataSourceSelectionCriteria' => '<p>The selection criteria that specifies which data sources to centralize. The selection criteria uses the same filter expression format as <code>LogGroupSelectionCriteria</code>, but operates on <code>DataSourceName</code> and <code>DataSourceType</code> operands. When both <code>LogGroupSelectionCriteria</code> and <code>DataSourceSelectionCriteria</code> are specified, a log event must match both criteria to be centralized.</p>', ], ], 'DataSources' => [ 'base' => NULL, 'refs' => [ 'ConfigurationSummary$DataSources' => '<p>The list of data sources that provide telemetry data to the pipeline.</p>', ], ], 'DatasetIntegrationSummaries' => [ 'base' => NULL, 'refs' => [ 'ListDatasetIntegrationsOutput$DatasetIntegrationSummaries' => '<p>The dataset integrations in your account.</p>', ], ], 'DatasetIntegrationSummary' => [ 'base' => '<p>Contains summary information about a dataset integration, including its ARN, associated IAM role, and creation and update timestamps, as returned by <code>ListDatasetIntegrations</code>.</p>', 'refs' => [ 'DatasetIntegrationSummaries$member' => NULL, ], ], 'DeleteCentralizationRuleForOrganizationInput' => [ 'base' => NULL, 'refs' => [], ], 'DeleteConnectorInput' => [ 'base' => NULL, 'refs' => [], ], 'DeleteConnectorOutput' => [ 'base' => NULL, 'refs' => [], ], 'DeleteDatasetIntegrationInput' => [ 'base' => NULL, 'refs' => [], ], 'DeleteS3TableIntegrationInput' => [ 'base' => NULL, 'refs' => [], ], 'DeleteTelemetryPipelineInput' => [ 'base' => NULL, 'refs' => [], ], 'DeleteTelemetryPipelineOutput' => [ 'base' => NULL, 'refs' => [], ], 'DeleteTelemetryRuleForOrganizationInput' => [ 'base' => NULL, 'refs' => [], ], 'DeleteTelemetryRuleInput' => [ 'base' => NULL, 'refs' => [], ], 'DeletionProtection' => [ 'base' => '<p>Specifies the deletion protection setting that a rule applies to the log groups that it creates. If you don\'t specify a value, the rule doesn\'t enable deletion protection. The following value is supported:</p> <ul> <li> <p> <code>ENABLED</code> – The rule enables deletion protection on log groups that it creates.</p> </li> </ul>', 'refs' => [ 'DestinationLogsConfiguration$LogGroupDeletionProtection' => '<p>Specifies whether this centralization rule enables deletion protection on the destination log groups that it creates. If you don\'t specify this setting, the rule doesn\'t enable deletion protection on the log groups that it creates. If you specify a backup Region in <code>BackupConfiguration</code>, the setting also applies to the log groups that the rule creates in the backup Region.</p> <p>When you set this to <code>ENABLED</code>, the rule enables deletion protection only on log groups that it creates after you enable the setting. It does not add deletion protection to log groups the rule created before you enabled the setting.</p> <p>If you remove this setting from the rule or delete the rule, deletion protection stays enabled on log groups that already have it. To delete one of these log groups, first disable deletion protection on the log group in the destination account.</p>', ], ], 'DestinationLogsConfiguration' => [ 'base' => '<p>Configuration for centralization destination log groups, including encryption and backup settings.</p>', 'refs' => [ 'CentralizationRuleDestination$DestinationLogsConfiguration' => '<p>Log specific configuration for centralization destination log groups.</p>', ], ], 'DestinationMetricsConfiguration' => [ 'base' => '<p>Configuration for centralization destination metrics, including backup settings.</p>', 'refs' => [ 'CentralizationRuleDestination$DestinationMetricsConfiguration' => '<p>Metric specific configuration for centralization destination metrics.</p>', ], ], 'DestinationProfilesConfiguration' => [ 'base' => '<p>Configuration for centralization destination profiles, including backup settings.</p>', 'refs' => [ 'CentralizationRuleDestination$DestinationProfilesConfiguration' => '<p>Profile-specific configuration for centralization destination profiles.</p>', ], ], 'DestinationType' => [ 'base' => NULL, 'refs' => [ 'TelemetryDestinationConfiguration$DestinationType' => '<p> The type of destination for the telemetry data (e.g., "Amazon CloudWatch Logs", "S3"). </p>', ], ], 'ELBLoadBalancerLoggingParameters' => [ 'base' => '<p> Configuration parameters for ELB load balancer logging, including output format and field delimiter settings. </p>', 'refs' => [ 'TelemetryDestinationConfiguration$ELBLoadBalancerLoggingParameters' => '<p> Configuration parameters specific to ELB load balancer logging when ELB is the resource type. </p>', ], ], 'EncryptedLogGroupStrategy' => [ 'base' => NULL, 'refs' => [ 'SourceLogsConfiguration$EncryptedLogGroupStrategy' => '<p>A strategy determining whether to centralize source log groups that are encrypted with customer managed KMS keys (CMK). ALLOW will consider CMK encrypted source log groups for centralization while SKIP will skip CMK encrypted source log groups from centralization.</p>', ], ], 'Encryption' => [ 'base' => '<p>Defines the encryption configuration for S3 Table integrations, including the encryption algorithm and KMS key settings.</p>', 'refs' => [ 'CreateS3TableIntegrationInput$Encryption' => '<p>The encryption configuration for the S3 Table integration, including the encryption algorithm and KMS key settings.</p>', 'GetS3TableIntegrationOutput$Encryption' => '<p>The encryption configuration for the S3 Table integration.</p>', ], ], 'EncryptionConflictResolutionStrategy' => [ 'base' => NULL, 'refs' => [ 'LogsEncryptionConfiguration$EncryptionConflictResolutionStrategy' => '<p>Conflict resolution strategy for centralization if the encryption strategy is set to CUSTOMER_MANAGED and the destination log group is encrypted with an AWS_OWNED KMS Key. ALLOW lets centralization go through while SKIP prevents centralization into the destination log group.</p>', ], ], 'EncryptionScope' => [ 'base' => '<p>Determines which newly created destination log groups are encrypted with the configured KMS key.</p>', 'refs' => [ 'LogsEncryptionConfiguration$EncryptionScope' => '<p>Determines which newly created destination log groups are encrypted with the configured <code>KmsKeyArn</code> when <code>EncryptionStrategy</code> is <code>CUSTOMER_MANAGED</code>.</p> <p>If you set this to <code>ENCRYPTED_SOURCE_ONLY</code> (the default), only destination log groups whose source log group is encrypted with a customer managed KMS key use the configured <code>KmsKeyArn</code>. Destination log groups derived from Amazon Web Services owned encrypted source log groups remain Amazon Web Services owned encrypted.</p> <p>If you set this to <code>NEW_DESTINATION_LOG_GROUPS</code>, every new destination log group created by this rule uses the configured <code>KmsKeyArn</code>, regardless of the source log group\'s encryption posture.</p> <p>This field is not valid when <code>EncryptionStrategy</code> is <code>AWS_OWNED</code>.</p>', ], ], 'EncryptionStrategy' => [ 'base' => NULL, 'refs' => [ 'LogsEncryptionConfiguration$EncryptionStrategy' => '<p>Configuration that determines the encryption strategy of the destination log groups. CUSTOMER_MANAGED uses the configured KmsKeyArn to encrypt newly created destination log groups.</p>', ], ], 'FailureReason' => [ 'base' => NULL, 'refs' => [ 'GetTelemetryEvaluationStatusForOrganizationOutput$FailureReason' => '